import{_ as o,o as s,c as a,aw as l}from"./chunks/framework.DLufY-ao.js";const y=JSON.parse('{"title":"React.Component.render()","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react/lifecycle/render.md","filePath":"wiki/dev-commit/framework-react/react/lifecycle/render.md"}'),t={name:"wiki/dev-commit/framework-react/react/lifecycle/render.md"};function n(c,e,r,p,i,d){return s(),a("div",null,[...e[0]||(e[0]=[l(`<h1 id="react-component-render" tabindex="-1">React.Component.render() <a class="header-anchor" href="#react-component-render" aria-label="Permalink to &quot;React.Component.render()&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong><code>ReactDOM.render ()</code></strong> - рендеринг элементов. Единственный обязательный метод в подклассе React.Component. При вызове он проверяет this.props и this.state. Возвращает дерево React-элементов, которые превращаются в DOM-элементы</p><blockquote><ul><li><em>return</em> - Элемент React / Массивы и фрагменты / Порталы / Строки и числа / Booleans или null</li></ul></blockquote></div><p><strong>Возвращаемые значения</strong></p><ul><li><em>Элемент React</em>. Обычно создаётся с помощью JSX. Указывает React, что рендерить: DOM-узел или пользовательский компонент. Например, <code>&lt;div /&gt;</code> или <code>&lt;MyComponent /&gt;</code></li><li><em>Массивы и фрагменты</em>. Возвращает несколько элементов из <code>render()</code></li><li><em>Порталы</em>. Рендерит несколько дочерних элементов в другое поддерево DOM</li><li><em>Строки и числа</em>. Рендерит текстовые DOM-узлы</li><li><em>Booleans или null</em>. Ничего не рендерит. Обычно необходим для поддержки паттерна <code>return test &amp;&amp; &lt;Child /&gt;</code>, где test - логическое значение</li></ul><p><strong>Информация</strong></p><ul><li>Функция <code>render()</code> должна быть чистой. Это означает, что она не изменяет состояние компонента, всегда возвращает один и тот же результат, не взаимодействует напрямую с браузером. Взаимодействовать с браузером необходимо в <code>componentDidMount()</code> или других методах жизненного цикла. Чистый <code>render()</code> делает компонент понятным</li></ul><h2 id="reactdom-render-рендеринг-элементов" tabindex="-1">ReactDOM.render() - рендеринг элементов <a class="header-anchor" href="#reactdom-render-рендеринг-элементов" aria-label="Permalink to &quot;ReactDOM.render() - рендеринг элементов&quot;">​</a></h2><ul><li><strong>Элементы</strong> - это то, «из чего сделаны» компоненты</li><li>В отличие от DOM-элементов, элементы React - это простые объекты, не отнимающие много ресурсов. React DOM обновляет DOM, чтобы он соответствовал переданным React-элементам</li><li><code>ReactDOM.render()</code> - рендеринг React-элемента в узел DOM</li><li>Элементы React иммутабельны. После создания элемента, нельзя изменить его потомков или атрибуты. Элемент похож на кадр в фильме: он отражает состояние интерфейса в конкретный момент времени</li></ul><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">ReactDOM.</span><span style="color:#4078F2;">render</span><span style="color:#383A42;">(&lt;</span><span style="color:#C18401;">App</span><span style="color:#383A42;"> /&gt;, document.</span><span style="color:#4078F2;">getElementById</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;root&quot;</span><span style="color:#383A42;">));</span></span></code></pre></div><h2 id="рендеринг" tabindex="-1">Рендеринг <a class="header-anchor" href="#рендеринг" aria-label="Permalink to &quot;Рендеринг&quot;">​</a></h2><ul><li>Элементы могут описывать и наши собственные компоненты</li><li>Когда React встречает подобный элемент, он собирает все JSX-атрибуты в один объект и передаёт их нашему компоненту. Этот объект называется «пропсы» (props)</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> Welcome</span><span style="color:#383A42;">(props) {</span></span>
<span class="line"><span style="color:#A626A4;">  return</span><span style="color:#383A42;"> &lt;</span><span style="color:#E45649;">h1</span><span style="color:#383A42;">&gt;Привет, </span><span style="color:#CA1243;">{</span><span style="color:#383A42;">props.</span><span style="color:#E45649;">name</span><span style="color:#CA1243;">}</span><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">h1</span><span style="color:#383A42;">&gt;;</span></span>
<span class="line"><span style="color:#383A42;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> element</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> &lt;</span><span style="color:#C18401;">Welcome</span><span style="color:#986801;"> name</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;Алиса&quot;</span><span style="color:#383A42;"> /&gt;;</span></span>
<span class="line"><span style="color:#383A42;">ReactDOM.</span><span style="color:#4078F2;">render</span><span style="color:#383A42;">(element, document.</span><span style="color:#4078F2;">getElementById</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;root&quot;</span><span style="color:#383A42;">));</span></span></code></pre></div><ol><li>Мы передаём React-элемент <code>&lt;Welcome name=&quot;Алиса&quot; /&gt;</code> в ReactDOM.render()</li><li>React вызывает наш компонент <code>&lt;Welcome&gt;</code> с пропсами</li><li>Наш компонент <code>&lt;Welcome&gt;</code> возвращает элемент <code>&lt;h1&gt;Привет, Алиса&lt;/h1&gt;</code> в качестве результата</li><li>React DOM делает минимальные изменения в DOM, чтобы получилось <code>&lt;h1&gt;Привет, Алиса&lt;/h1&gt;</code></li></ol>`,13)])])}const u=o(t,[["render",n]]);export{y as __pageData,u as default};
